const fyAvatar=(name,alt)=>'<img src="'+asset(name)+'" alt="'+esc(alt)+'" onerror="this.src=\'assets/xiaoyi.png\'">';
function assistantMini(context,question){return `<div class="assistant-mini"><img src="${asset('xiaoyi')}" alt="小忆头像"><div><strong>小忆</strong><span>${esc(question||'我会安静听你讲。')}</span></div><button data-final="ai-open" data-context="${context}">对话 ›</button></div>`;}
function guideImg(g){return g.src||asset(g.img)}
function syncPhotoGuides(){for(const p of state.addedPhotos){const id=`self-photo-${p.id}`;if(GUIDES.some(g=>g.id===id))continue;const m=memories.find(x=>x.id===p.id);GUIDES.push({id,kind:'本人照片',source:`本人拍照 · ${p.title}`,title:p.title,q:`看着这张照片，你最先想起那天的什么？`,img:'old-workbench',src:m?.src||null,method:'照片来源先由本人确认，问题只邀请本人讲记得的画面。',photoId:p.id})}for(const g of GUIDES.filter(x=>x.photoId)){g.src=memories.find(m=>m.id===g.photoId)?.src||g.src}}
function syncEvidenceGuides(){for(const f of state.addedFiles){const id=`file-guide-${f.id}`;if(GUIDES.some(g=>g.id===id))continue;GUIDES.push({id,kind:'文件线索',source:`协作端上传 · ${f.name}`,title:f.title,q:`看到这份${f.title}，你先想起它涉及的哪一段经历？`,img:'expo',method:'文件本身只是待核对线索，问题不复述其内容为事实。'})}for(const c of state.chatClues){const id=`chat-guide-${c.title}`;if(GUIDES.some(g=>g.id===id))continue;GUIDES.push({id,kind:'聊天线索',source:'协作端上传 · 微信线索',title:c.title,q:`家人提起${c.title}，你自己最先想起哪件事？`,img:'familytrip',method:'聊天里的说法不直接进入正文；只给本人一个开放的起话头。'})}}
function finalTabs(){const tabs=[['home','录音','home'],['stories','经历','stories'],['upload','＋','plus'],['community','广场','community'],['books','我的','books']];return tabs.map(([id,label,icon])=>`<button class="tab ${state.route===id?'active':''} ${id==='upload'?'tab-upload':''}" ${id==='upload'?'data-final="upload-sheet"':`data-route="${id}"`} aria-label="${id==='upload'?'上传内容':label}"><svg viewBox="0 0 24 24" aria-hidden="true">${id==='upload'?'<path d="M12 4v16M4 12h16"/>':icons[icon]}</svg><span>${id==='upload'?'上传':label}</span></button>`).join('');}
function guideCard(g){return `<div class="guide-card soft-card"><img src="${guideImg(g)}" alt="${esc(g.title)}"><div class="guide-scrim"></div><div class="guide-content"><small>小忆问 · ${esc(g.source)}</small><h2>${esc(g.title)}</h2><p>“${esc(g.q)}”</p><div class="guide-actions"><button data-final="guide-record">讲这个话题</button><button data-final="guide-next">换一个 ›</button></div></div></div>`;}
function finalHome(){const g=GUIDES[state.guideIndex];const featured=people.slice(0,3);const photoGuides=GUIDES.filter(x=>x.source.includes('拍照')||x.source.includes('上传'));return `<section class="screen final-home"><div class="topline"><span class="eyebrow">陈建华 · 我的回忆</span><button class="tiny-action" data-route="books">我的书 ›</button></div><h1 class="hello">今天，想从哪里<br>开始讲？</h1><button class="direct-record" data-final="agent-demo-record"><span class="mic-orb">●</span><span><strong>直接开讲</strong><small>录一段，看小忆整理成文稿</small></span><b>›</b></button>${guideCard(g)}<div class="section-head"><h2>他们想听的故事</h2><button data-route="people">人物关系 ›</button></div><div class="people-strip home-people-three">${featured.map(p=>`<button class="person-card" data-person="${p.id}">${avatar(p)}<span class="name">${p.name}</span><span class="rel">${p.rel}</span><div class="counts">${p.question.length} 条提问 · ${activeRecords(p).length} 条语音</div>${unreadCount(p)?'<i class="unread-dot"></i>':''}</button>`).join('')}</div><div class="section-head"><h2>从已有线索聊起</h2><button data-final="all-guides">全部话题 ›</button></div><div class="clue-grid">${photoGuides.slice(0,4).map(x=>`<button data-final="select-guide" data-id="${x.id}"><img src="${guideImg(x)}" alt=""><small>${esc(x.source)}</small><strong>${esc(x.title)}</strong></button>`).join('')}</div></section>`;}
function allGuidesPage(){return `<section class="screen subscreen">${headerBack('讲述')}<span class="eyebrow">小忆准备的话题</span><h1 class="subheading">从想说的那一件开始</h1><p class="subtext">线索只用来选话题，经过仍由你来讲。</p>${assistantMini('guides','你想从哪一张照片或哪一件小事说起？')}${['默认话题','本人拍照','协作端上传'].map(group=>`<div class="section-head"><h2>${group}</h2></div>${GUIDES.filter(g=>group==='默认话题'?g.source==='默认话题':group==='本人拍照'?g.source.includes('本人'):g.source.includes('协作')||g.source.includes('思远')).map(g=>`<button class="guide-row" data-final="select-guide" data-id="${g.id}"><img src="${guideImg(g)}" alt=""><span><small>${esc(g.source)}</small><strong>${esc(g.title)}</strong><em>“${esc(g.q)}”</em></span><b>›</b></button>`).join('')}`).join('')}<div class="method-card soft-card"><strong>小忆怎样问</strong><p>先听你讲完，再按线索选方向，一次只问一个问题。协作内容不会直接写进正文。</p><button data-final="ai-open" data-context="guides">和小忆聊聊 ›</button></div></section>`;}
function finalStories(){if(state.storiesView==='timeline')return finalTimeline();const vis=EVENTS.filter(e=>!state.deletedStories.includes(e.id));return `<section class="screen"><div class="topline"><span class="eyebrow">我的经历</span><button class="tiny-action" data-final="upload-sheet">＋ 添加内容</button></div><h1 class="subheading">说过的，都在这里</h1><p class="subtext">${vis.length} 件经历 · ${vis.reduce((n,e)=>n+e.segments.length,0)+state.added.length} 段语音</p>${assistantMini('stories','你要补充哪一个片段？')}<div class="view-switch"><button class="selected" data-extra="stories-list">故事列表</button><button data-extra="stories-timeline">照片时间轴</button></div>${[...new Set(vis.map(e=>e.period))].map(period=>`<div class="section-head"><h2>${period}</h2></div>${vis.filter(e=>e.period===period).map(eventCard).join('')}`).join('')}<div style="height:18px"></div><button class="primary green full" data-action="record">讲一段新的经历</button></section>`;}
function finalTimeline(){const m=memories[state.memoryIndex];return `<section class="screen timeline-final"><div class="topline"><span class="eyebrow">经历 · 照片时间轴</span><button class="tiny-action" data-final="upload-sheet">＋ 照片</button></div><h1 class="subheading">沿着照片，走过这些年</h1>${assistantMini('timeline','停在一张照片上，我陪你想起那一天。')}<div class="view-switch"><button data-extra="stories-list">故事列表</button><button class="selected" data-extra="stories-timeline">照片时间轴</button></div><div class="timeline-stage"><div class="timeline-track" id="photo-stream">${memories.map((x,i)=>`<button class="timeline-photo ${i===state.memoryIndex?'active':''}" data-final="focus-memory" data-id="${i}"><img src="${memImg(x)}" alt="${esc(x.title)}"><span>${esc(x.year)}</span></button>`).join('')}</div></div><div class="timeline-years">${memories.map((x,i)=>`<button class="${i===state.memoryIndex?'active':''}" data-final="focus-memory" data-id="${i}">${esc(x.year)}</button>`).join('')}</div><div id="timeline-story">${finalMemoryText(m)}</div><div class="timeline-actions"><button class="ghost" data-final="timeline-play">▶ 听片段</button><button class="ghost" data-final="timeline-text">查看文字</button><button class="primary green" data-action="record-memory">补充讲述</button></div></section>`;}
function finalMemoryText(m){const p=person(m.person);return `<div class="timeline-story soft-card"><small>${esc(m.date)} · ${esc(m.place)}</small><h2>${esc(m.title)}</h2><p>${esc(m.story)}</p></div>${p?`<button class="timeline-person" data-person="${p.id}">${avatar(p,37)}<span><strong>${p.name}</strong><small>${p.rel} · 与这段经历有关</small></span><b>›</b></button>`:''}`;}
function coverVisual(b){const img=b.id==='life'?'narrator':b.id==='work'?'workshop':'huangshan';return `<div class="cover-design cover-${b.id}"><img src="${asset(img)}" alt=""><div class="cover-overlay"><small>${b.id==='life'?'陈建华 · 口述自传':b.id==='work'?'华辰二十六年':'山河与家人'}</small><strong>${esc(b.title)}</strong><span>陈建华　著</span></div></div>`;}
function finalBooks(){return `<section class="screen bookshelf-final"><div class="topline"><span class="eyebrow">我的回忆册</span><button class="tiny-action" data-extra="new-book">＋ 新建</button></div><h1 class="subheading">我的书架</h1>${assistantMini('books','想把哪一段经历放进书里？')}<div class="shelf-top"></div><div class="book-shelf">${books.map(b=>`<button class="shelf-book book-${b.id}" data-book="${b.id}">${coverVisual(b)}<span>${esc(b.title)}</span></button>`).join('')}</div><div class="shelf-bottom"></div><div class="section-head"><h2>继续制作</h2></div><div class="make-actions"><button data-extra="new-book">＋ 制作新版本</button><button data-final="order-open" data-id="life">选择成品与册数</button><button data-extra="export" data-id="life">导出电子稿</button></div><div class="section-head"><h2>最近的页</h2></div><button class="timeline-peek" data-book="life"><img src="${asset('father')}" alt="父亲的照片"><div><small>人生故事 · 第一章</small><strong>木匠父亲的工作台</strong><span>刨花味，我现在还记得</span></div><b>›</b></button></section>`;}
function myPage(){return finalBooks().replace('<span class="eyebrow">我的回忆册</span>','<span class="eyebrow">我的空间</span>').replace('<h1 class="subheading">我的书架</h1>',`<div class="my-title-row"><h1 class="subheading">我的</h1><button class="my-follow-inline" data-final="my-follow"><span class="follow-faces"><img src="${asset('community-yuzhen')}" alt=""><img src="${asset('community-jianguo')}" alt=""><img src="${asset('pro-shen')}" alt=""></span><strong>我的关注</strong><b>›</b></button></div><div class="section-head"><h2>我的书架</h2></div>`)}
const FOLLOW_NEWS=[
 {id:'photo',pro:'shen',title:'翻旧照片时，先听他讲“画面外”的事',text:'一张照片不只记着拍摄的那一秒。陪长辈看照片时，我常先请他看看背景里的一处小物件，再等他自己把那天讲完整。',date:'9月15日'},
 {id:'voice',pro:'lin',title:'一段原声怎样留在书页上',text:'书可以重新排版，讲述人的停顿、重复和一句很口语的话却值得留着。读者听到原声时，往往能认出家里那个熟悉的人。',date:'9月12日'},
 {id:'chapter',pro:'chen',title:'整理一段工作回忆，从场景开始',text:'比起先问“你最成功的一次是什么”，我更愿意问第一次到现场时看见了什么。人物、物件和声音出现后，故事会自己往前走。',date:'9月8日'}
];
function followPage(){return `<section class="screen subscreen follow-page">${headerBack('我的')}<h1 class="subheading">我的关注</h1><div class="section-head"><h2>互关好友</h2></div>${COMMUNITY.slice(0,2).map(n=>`<button class="follow-person" data-final="friend-open" data-id="${n.id}"><img src="${asset(n.avatar)}" alt="${esc(n.name)}头像"><span><strong>${esc(n.name)}</strong><small>互相关注 · 可以分享回忆册</small></span><b>对话 ›</b></button>`).join('')}<div class="section-head"><h2>关注的访谈者</h2></div>${PROS.filter(p=>p.id==='shen'||p.id==='lin').map(p=>`<button class="follow-person" data-extra="pro" data-id="${p.id}"><img src="${asset(p.avatar)}" alt="${esc(p.name)}头像"><span><strong>${esc(p.name)}</strong><small>${esc(p.title)} · ${p.live?'正在直播':'新内容'}</small></span><b>主页 ›</b></button>`).join('')}<div class="section-head"><h2>他们最近写的</h2></div>${FOLLOW_NEWS.map(n=>{const p=PROS.find(x=>x.id===n.pro);return `<button class="news-card" data-final="news-open" data-id="${n.id}"><img src="${asset(p.avatar)}" alt=""><span><small>${p.name} · ${n.date}</small><strong>${esc(n.title)}</strong><em>${esc(n.text)}</em></span><b>›</b></button>`}).join('')}</section>`;}
function friendPage(){const n=COMMUNITY.find(x=>x.id===state.followFriend)||COMMUNITY[0];return `<section class="screen subscreen friend-page">${headerBack('我的关注')}<div class="friend-head"><img src="${asset(n.avatar)}" alt="${esc(n.name)}头像"><span><strong>${esc(n.name)}</strong><small>互相关注 · 本地对话预览</small></span></div><div class="friend-bubbles"><div class="friend-bubble"><small>${esc(n.name)}分享了回忆册</small>${communityBook(n)}<p>“这本书里有我在车间那几年，你有空翻翻。”</p></div>${state.friendMessages.filter(m=>m.to===n.id).map(m=>`<div class="friend-bubble mine"><small>我分享给${esc(n.name)}</small><p>${esc(m.text)}</p></div>`).join('')}</div><div class="section-head"><h2>分享我的书</h2></div><div class="friend-books">${books.slice(0,3).map(b=>`<button data-final="friend-share-book" data-id="${b.id}">${coverVisual(b)}<strong>${esc(b.title)}</strong></button>`).join('')}</div><form id="friend-text-form" class="ai-compose"><input name="text" maxlength="180" placeholder="写一句想说的话…" required><button type="submit">保存</button></form><p class="ai-note">这里只展示互相分享的交互方式，不会发送给真实好友。</p></section>`;}
function newsPage(){const n=FOLLOW_NEWS.find(x=>x.id===state.followNews)||FOLLOW_NEWS[0],p=PROS.find(x=>x.id===n.pro);return `<section class="screen subscreen">${headerBack('我的关注')}<div class="news-author"><img src="${asset(p.avatar)}" alt="${p.name}头像"><span><strong>${p.name}</strong><small>${p.title} · ${n.date}</small></span></div><h1 class="subheading">${esc(n.title)}</h1><p class="news-body">${esc(n.text)}</p><button class="primary green full" data-extra="pro" data-id="${p.id}">查看${p.name}的服务</button></section>`;}
function editedPage(b,i){const p=b.pages[i];return p?{...p,text:pageEdits[`${b.id}-${i}`]??p.text}:null;}
function spreadPageContent(b,i,side){const p=editedPage(b,i);if(!p)return `<div class="spread-page blank-page"><span>· ${esc(b.title)} ·</span></div>`;return `<button class="spread-page spread-${b.id} ${side}" data-final="page-full" data-id="${i}"><small>${esc(p.label||b.kind)}</small>${p.photo?`<img src="${asset(p.photo)}" alt="${esc(p.title)}">`:''}<h3>${esc(p.title)}</h3><p>${esc(p.text||p.subtitle||'')}</p><i>${i+1}</i><em>点开阅读和编辑</em></button>`;}
const BOOK_PROG={life:[62,'已收录 12 段原声 · 约完成六成'],work:[40,'已收录 6 段原声 · 第二章制作中'],travel:[18,'已收录 2 段原声 · 刚开始']};
function finalReader(){const b=books.find(x=>x.id===state.bookId)||books[0];const closed=state.pageIndex===0;const left=state.pageIndex,right=left+1;const bp=BOOK_PROG[b.id]||[10,''];return `<section class="screen subscreen reader-final">${headerBack('我的书架')}<div class="book-reader-head"><small>${esc(b.kind)}</small><h1>${esc(b.title)}</h1><div class="reader-prog"><i style="width:${bp[0]}%"></i></div><p class="reader-prog-t">${bp[1]} · 完成 ${bp[0]}%</p></div>${assistantMini('reader','这一页里，有没有你想补充的原话？')}${closed?`<button class="closed-book" data-final="open-book">${coverVisual(b)}<span>翻开 ›</span></button>`:`<div class="spread-shell" id="spread-shell"><div class="spread-gutter"></div>${spreadPageContent(b,left,'left')}${spreadPageContent(b,right,'right')}</div>`}<div class="reader-controls"><button data-final="spread-prev" ${closed?'disabled':''}>‹ 上一页</button><span>${closed?'封面':`${left+1}–${Math.min(right+1,b.pages.length)} / ${b.pages.length}`}</span><button data-final="${closed?'open-book':'spread-next'}" ${!closed&&right>=b.pages.length-1?'disabled':''}>下一页 ›</button></div><div class="reader-extra"><button class="ghost" data-extra="export" data-id="${b.id}">导出电子稿</button><button class="primary" data-final="order-open" data-id="${b.id}">制作成品</button></div></section>`;}
function sentenceSpans(text){return String(text||'').split(/(?<=[。！？\n])/).filter(x=>x.trim()).map((s,i)=>`<span class="reader-segment ${state.readIndex===i?'reading':''}" data-sentence="${i}">${esc(s)}</span>`).join('');}
function pageQuestions(p){const text=String(p.text||'');if(/黄先生|出口订单|广交会/.test(text))return {detail:'你说的那个黄先生，你记得他全名吗？',scene:'你说拿计算器比划，那个计算器是什么样的？'};if(/父亲|工作台|木匠/.test(text))return {detail:'你提到父亲的工作台，它以前放在屋里的哪一处？',scene:'父亲做木工时，哪一种声音你现在还记得？'};if(/美凤/.test(text))return {detail:'说到美凤，你还想补充你们一起做过的哪件小事？',scene:'那一天周围是什么样，你还记得吗？'};return {detail:'这一页里提到的人，你还想补充哪一个细节？',scene:'这件事发生时，周围哪个画面你还记得？'};}
function fullPage(){const b=books.find(x=>x.id===state.bookId)||books[0],i=state.fullPageIndex,p=editedPage(b,i);if(!p)return finalReader();const key=`${b.id}-${i}`,qs=pageQuestions(p),q=qs[state.pageAiQuestion]||qs.detail,note=state.pageNotes[key]||'';return `<section class="screen subscreen fullpage-final">${headerBack(b.title)}<div class="fullpaper fullpaper-${b.id}"><small>${esc(p.label||b.kind)}</small>${p.photo?`<img src="${asset(p.photo)}" alt="${esc(p.title)}">`:''}<h1>${esc(p.title)}</h1>${state.inlineEditing?`<div class="fullpaper-text editing" id="fullpaper-edit" contenteditable="true" aria-label="编辑本页文字">${esc(p.text||'')}</div>`:`<div class="fullpaper-text" id="fullpaper-text">${sentenceSpans(p.text||p.subtitle)}</div>`}<span class="fullpaper-number">${i+1}</span></div><div class="fullpage-actions"><button data-final="${state.inlineEditing?'save-page-edit':'edit-page'}">${state.inlineEditing?'保存':'编辑本页'}</button><button data-final="read-page">${state.readIndex>=0?'停止朗读':'▶ 朗读本页'}</button></div><p class="subtext">朗读时正在读的句子会标记在书页上。</p>${xySay(`“${esc(q)}”`,`<button class="xy-chip ${state.pageAiQuestion==='detail'?'sel':''}" data-final="page-question" data-id="detail">补人物或物件</button><button class="xy-chip ${state.pageAiQuestion==='scene'?'sel':''}" data-final="page-question" data-id="scene">补一个场景</button><button class="xy-chip" data-final="page-question-speak">▶ 听问题</button><button class="xy-chip" data-final="page-record"><img src="assets/ic-mic.png" alt="">语音回答</button>`)}<form id="page-ai-form" class="page-ai-compose"><input name="reply" maxlength="350" value="${esc(note)}" placeholder="也可以打字告诉她…"><button type="submit">记到边注</button></form>${note?`<p class="page-note-saved">已记在第 ${i+1} 页的边注里。</p>`:''}</section>`;}
function editPage(){const b=books.find(x=>x.id===state.bookId),i=state.fullPageIndex,p=editedPage(b,i);return `<section class="screen subscreen">${headerBack(b.title)}<span class="eyebrow">编辑第 ${i+1} 页</span><h1 class="subheading">${esc(p.title)}</h1><p class="subtext">改动只保存到当前浏览器的预览书页。</p><form id="final-edit-form" class="full-form"><label>这一页的文字<textarea name="text" maxlength="1400" required>${esc(p.text||'')}</textarea></label><button class="primary full" type="submit">保存这一页</button></form></section>`;}
function filePage(){return `<section class="screen subscreen">${headerBack('上传内容')}<span class="eyebrow">文件线索</span><h1 class="subheading">存下一份旧文件</h1><p class="subtext">旧订单、证件、手写记录都可先存下；小忆只据此选话题，正文由你确认。</p><form id="final-file-form" class="full-form"><label>选择文件<input name="file" type="file" accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png" required></label><label>这是什么文件<input name="title" maxlength="40" required placeholder="如：2001 年的第一份出口订单"></label><label>线索说明<textarea name="note" maxlength="240" placeholder="可记下谁提供、日期是否确定"></textarea></label><button class="primary full" type="submit">保存文件线索</button></form><div class="section-head"><h2>已保存的文件</h2></div>${state.addedFiles.map(f=>`<div class="file-row"><span class="file-icon">▤</span><span><strong>${esc(f.title)}</strong><small>${esc(f.name)} · ${esc(f.note||'待本人确认')}</small></span><button data-final="file-delete" data-id="${f.id}">删除</button></div>`).join('')||'<div class="empty">还没有保存文件。</div>'}</section>`;}
openAudioDb=function(){return new Promise((resolve,reject)=>{const req=indexedDB.open('memo-prototype-audio',3);req.onupgradeneeded=()=>{for(const name of ['clips','photos','files'])if(!req.result.objectStoreNames.contains(name))req.result.createObjectStore(name)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})};
async function putEvidenceFile(id,file){try{const db=await openAudioDb(),tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);await new Promise((ok,no)=>{tx.oncomplete=ok;tx.onerror=no});db.close();return true}catch{return false}}
async function deleteEvidenceFile(id){try{const db=await openAudioDb(),tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);db.close()}catch{}}
const formats=[['hard','精装实体册',128],['soft','平装实体册',79],['mini','照片小册',59],['pdf','电子 PDF 版',49],['audio','有声阅读版',68],['bundle','实体册 + 电子版',158]];
function finalOrder(){const b=books.find(x=>x.id===state.orderBook)||books[0],f=formats.find(x=>x[0]===state.finalFormat)||formats[0],qty=Math.max(1,Math.min(99,Number(state.orderQty)||1));return `<section class="screen subscreen order-final">${headerBack('我的')}<span class="eyebrow">《${esc(b.title)}》</span><h1 class="subheading">选择你的成品</h1>${assistantMini('order','想把这本书做成几册，送给谁？')}<div class="section-head"><h2>版本</h2></div>${formats.map(x=>`<button class="option-row ${x[0]===state.finalFormat?'selected':''}" data-final="order-format" data-id="${x[0]}"><span><strong>${x[1]}</strong><small>${x[0]==='audio'?'朗读段落与声音标记':x[0]==='pdf'?'电子文件':x[0]==='mini'?'轻巧照片装帧':'纸张与装帧预览'}</small></span><b>¥${x[2]}</b></button>`).join('')}<div class="section-head"><h2>数量</h2></div><div class="qty-field"><button data-final="qty-minus">−</button><input id="order-qty" type="number" min="1" max="99" value="${qty}" aria-label="购买数量"><button data-final="qty-plus">＋</button></div><div class="price-total soft-card"><span>${f[1]} · ${qty} 份</span><strong>¥${f[2]*qty}</strong></div><button class="primary full" data-final="save-final-order">保存制作方案</button></section>`;}
