recordFinal=function(){const p=state.recordFor?person(state.recordFor):null,q=state.recordTitle||`今天你最想先讲${p?'和'+p.name+'有关的':'的'}哪件事？`;return `<section class="screen subscreen record-final ios-record-screen">${headerBack('讲一段故事')}<div class="record-question"><img src="${asset('xiaoyi')}" alt="小忆头像"><span><small>小忆问</small><strong>“${esc(q)}”</strong></span><button data-final="record-question-speak" aria-label="朗读问题">▶</button></div><h1 class="subheading">${p?`和${p.name}有关的故事`:'把这段经历讲下来'}</h1><div class="record-panel"><div class="record-orb ${state.recording?'':'paused'}">${state.recording?'◉':'<img class="orb-mic" src="assets/ic-mic.png" alt="">'}</div><div class="wave ${state.recording?'':'still'}">${Array.from({length:21},(_,i)=>`<i style="--h:${14+(i*17)%54}px;--d:${(i%7)*-0.13}s"></i>`).join('')}</div><div class="record-time">${formatSecs(state.recordSeconds)}</div>${state.recording?`<div class="record-transcript live-transcript"><small>正在形成文字</small><p id="live-transcript-lines">${liveTranscriptLines(state.recordSeconds)}</p></div>`:'<p class="record-help">点按按钮，开始记录这段讲述。</p>'}<div class="record-actions">${state.recording?'<button class="ghost" data-action="pause-record">暂停</button><button class="primary" data-action="finish-record">完成录制</button>':'<button class="primary full" data-action="start-record">开始录下我的原声</button>'}</div></div></section>`};
const AGENT_RAW='这张照片啊，是零一年……嗯……广交会。我们第一次去参加。展位是最小的那种，三米乘三米，在角落里。我带了两个样品箱，自己扛进去的。嗯……那天来了一个马来西亚的客户，华裔，姓黄。他看了看我们的产品，问了几个技术参数，嗯，留了一张名片。我当时英文不行，拿个计算器跟他比划价格。后来这个黄先生给了我们第一张出口订单，三万美金。我高兴得一晚上没睡。三万美金，那时候对我是一笔很大的钱。交货那天我自己去码头，就站在那里看着集装箱装上去，心里说不出是什么感觉。合同签完我没敢告诉国平，怕他以为我在吹牛。等货真的装上了船，我才跟他说。他愣了一下，然后笑了，说行啊老陈。那个黄先生后来跟了我们十几年。每年他来中国我都请他吃饭。他不会用筷子，每次都让我教他，但他每次都学不会。';
const AGENT_CLEAN='这张照片啊，是零一年广交会。我们第一次去参加。展位是最小的那种，三米乘三米，在角落里。我带了两个样品箱，自己扛进去的。那天来了一个马来西亚的客户，华裔，姓黄。他看了看我们的产品，问了几个技术参数，留了一张名片。我当时英文不行，拿个计算器跟他比划价格。后来这个黄先生给了我们第一张出口订单，三万美金。我高兴得一晚上没睡。三万美金，那时候对我是一笔很大的钱。交货那天我自己去码头，就站在那里看着集装箱装上去，心里说不出是什么感觉。合同签完我没敢告诉国平，怕他以为我在吹牛。等货真的装上了船，我才跟他说。他愣了一下，然后笑了，说行啊老陈。那个黄先生后来跟了我们十几年。每年他来中国我都请他吃饭。他不会用筷子，每次都让我教他，但他每次都学不会。';
const AGENT_QUESTIONS={person:'你说的那个黄先生，你记得他全名吗？',timeline:'你说黄先生给了你们订单——是展会那天就谈妥了，还是后来又联系的？',chapter:'从展会上认识到拿到订单，这中间还有哪一步是你想留在书里的？'};
function demoRecordPage(){return `<section class="screen subscreen agent-record ios-record-screen">${headerBack('讲述')}<span class="eyebrow">展会照片 · 工作回忆第二章</span><div class="record-question"><img src="${asset('xiaoyi')}" alt="小忆头像"><span><small>小忆问</small><strong>“看着这张合影，你记得那天是怎么开始的吗？”</strong></span><button data-final="demo-question-speak" aria-label="朗读问题">▶</button></div><button class="agent-why" data-final="agent-why">为什么这样问？ ›</button>${state.agentWhy?'<div class="agent-reason soft-card">照片给了话题方向。思远标注的“2001 年广交会”还没有由你确认，所以小忆没有把它放进问题里。</div>':''}<div class="record-panel"><div class="record-orb ${state.demoRecording?'':'paused'}">${state.demoRecording?'◉':'<img class="orb-mic" src="assets/ic-mic.png" alt="">'}</div><div class="wave ${state.demoRecording?'':'still'}">${Array.from({length:21},(_,i)=>`<i style="--h:${14+(i*17)%54}px;--d:${(i%7)*-0.13}s"></i>`).join('')}</div><div class="record-time">${formatSecs(state.demoSeconds)}</div>${state.demoRecording?`<div class="record-transcript live-transcript"><small>正在形成文字</small><p id="live-transcript-lines">${liveTranscriptLines(state.demoSeconds)}</p></div>`:'<p class="record-help">点按按钮，开始记录这段讲述。</p>'}<div class="record-actions">${state.demoRecording?'<button class="primary full" data-final="demo-finish">完成录制</button>':'<button class="primary full" data-final="demo-start">开始录下我的原声</button>'}</div></div></section>`;}
function agentReviewPage(){return `<section class="screen subscreen agent-review">${headerBack('讲述')}<span class="eyebrow">事件标题 · 工作回忆第二章</span><h1 class="subheading">华辰第一个出口订单</h1><div class="agent-state"><span>原声 → 整理 → 本人确认</span><strong>${state.agentConfirmed?'已确认':'待你确认'}</strong></div><div class="draft-switch"><button data-final="draft-clean" class="${state.agentRaw?'':'selected'}">整理后的完整文稿</button><button data-final="draft-raw" class="${state.agentRaw?'selected':''}">看原文</button></div><div class="agent-draft soft-card"><small>${state.agentRaw?'原始逐字稿 · 保留停顿与重复':'纠错并整理后的文稿 · 默认显示'}</small><p>${esc(state.agentRaw?AGENT_RAW:AGENT_CLEAN)}</p></div><div class="agent-decisions soft-card"><strong>小忆这样整理</strong><p>去掉三个没有信息的“嗯”；“三万美金”说了两次，都保留；“零一年”仍用你的说法。国平补充的月份只放在待确认边注里。</p><div class="uncertain-note"><small>待确认</small><span>你说：零一年<br>国平补充：2001 年春交会</span></div></div>${!state.agentConfirmed?`<div class="review-actions"><button data-final="draft-read">▶ 朗读文稿</button><button data-final="agent-confirm">是，就这样</button></div><button class="tiny-action" data-final="draft-raw" style="width:100%">再看一次原文</button>`:`<div class="agent-followup"><div class="followup-person xy-look"><img src="${asset('xiaoyi')}" alt="小忆头像"><span><small>小忆 · 只补一个问题，也可以直接保存</small><strong>“${AGENT_QUESTIONS[state.agentQuestion]}”</strong></span></div><div class="followup-options three"><button data-final="followup-select" data-id="person" class="${state.agentQuestion==='person'?'selected':''}">补人物</button><button data-final="followup-select" data-id="timeline" class="${state.agentQuestion==='timeline'?'selected':''}">补时间线</button><button data-final="followup-select" data-id="chapter" class="${state.agentQuestion==='chapter'?'selected':''}">补章节空白</button></div><form id="agent-supplement-form" class="full-form"><label>想补充的话<textarea name="supplement" maxlength="350" placeholder="想起来就讲；不想补也可以跳过">${esc(state.agentSupplement)}</textarea></label><button class="ghost" type="submit">先记在边注</button></form>${state.agentSupplement?'<p class="supplement-saved">这句补充已放在边注；正文仍保留刚确认的原话。</p>':''}<button class="primary green full" data-final="agent-save">保存这件经历</button><button class="tiny-action" data-final="agent-save" style="width:100%;margin-top:10px">今天先不补充，直接保存</button></div>`}</section>`;}
function agentDonePage(){return `<section class="screen subscreen agent-done">${headerBack('讲述')}<div class="success-orb">✓</div><h1 class="subheading">华辰第一个出口订单</h1><p class="subtext">这段经历已经按你确认的说法收好了。</p>${xySay('今天先到这里，还是再录一段？',`<button class="xy-chip" data-final="agent-rest">回到首页</button><button class="xy-chip sel" data-final="agent-more"><img src="assets/ic-mic.png" alt="">再录一段</button>`)}</section>`;}
function aiPage(){const q=aiQuestion();return `<section class="screen subscreen ai-page">${headerBack('小忆')}<div class="ai-profile"><img src="${asset('xiaoyi')}" alt="小忆头像"><span><strong>小忆</strong><small>温和的访谈者 · 语音优先</small></span><i></i></div><div class="ai-dialogue"><div class="ai-bubble"><small>小忆</small><p>${esc(q)}</p><button data-final="ai-speak">▶ 听问题</button></div>${state.aiMessages.slice(-6).map(m=>`<div class="ai-bubble ${m.from==='me'?'mine':''}"><small>${m.from==='me'?'我':'小忆'}</small><p>${esc(m.text)}</p></div>`).join('')}</div><div class="ai-examples"><button data-final="ai-example" data-id="那一年我第一次出省跑业务。">第一次跑业务</button><button data-final="ai-example" data-id="我想从一张老照片说起。">从老照片说起</button><button data-final="ai-example" data-id="我还没想好，先听一个问题。">换个问题</button></div><form id="ai-text-form" class="ai-compose"><input name="message" maxlength="350" placeholder="也可以先打字告诉小忆…" aria-label="给小忆的文字"><button type="submit">发送</button></form><div class="ai-voice-actions"><button data-final="ai-listen"><img class="opt-ic" src="assets/ic-mic.png" alt="">语音对话</button><button data-final="ai-record">录一段故事</button></div><p class="ai-note">对话为本地演示。正式录音时，小忆安静聆听。</p></section>`;}
let timelineTimer=null,recognizer=null,readingUtterance=null;
function finalRender(){syncPhotoGuides();syncEvidenceGuides();clearInterval(timelineTimer);timelineTimer=null;const pages={home:finalHome,stories:finalStories,people:peopleFinal,person:personFinal,audioall:audioAllPage,community:communityPage,'community-detail':communityDetail,'pro-detail':proDetail,books:myPage,follow:followPage,friend:friendPage,news:newsPage,reader:finalReader,fullpage:fullPage,editpage:editPage,order:finalOrder,'order-done':orderDonePage,'new-book':newBookPage,photo:photoPage,photoform:photoFormPage,chat:chatPage,file:filePage,guides:allGuidesPage,ai:aiPage,topic:topicPage,ready:readyPage,record:recordFinal,'agent-demo-record':demoRecordPage,'agent-review':agentReviewPage,'agent-done':agentDonePage,preview:previewWithActions,'record-done':recordDonePage};const fn=pages[state.route]||finalHome;viewport.innerHTML=fn()+(state.deleteId?dialog():'')+(state.storySegment?segmentSheet():'')+(state.storyDelete?confirmStorySheet():'')+(state.uploadSheet?uploadOverlay():'');const main=['home','stories','community','books'].includes(state.route);tabbar.innerHTML=main?finalTabs():'';tabbar.classList.toggle('hidden',!main);if(state.route==='stories'&&state.storiesView==='timeline'){setTimeout(()=>focusTimeline(false),40);timelineTimer=setInterval(()=>{if(!state.timelinePaused){state.memoryIndex=(state.memoryIndex+1)%memories.length;focusTimeline(true)}},4000)}}
render=finalRender;
back=function(){if(state.uploadSheet){state.uploadSheet=false;return render()}if(state.route==='ai')return route(state.aiOrigin||'home');if(state.route==='agent-review')return route('agent-demo-record');if(state.route==='agent-done')return route('home');if(state.route==='agent-demo-record')return route('home');if(state.route==='friend'||state.route==='news')return route('follow');if(state.route==='follow')return route('books');if(state.route==='fullpage')return route('reader');if(state.route==='editpage')return route('fullpage');if(state.route==='guides')return route('home');if(state.route==='people')return route('home');if(state.route==='person')return route(state.personFrom&&state.personFrom!=='person'?state.personFrom:'people');if(state.route==='reader')return route('books');if(state.route==='order')return route('books');if(state.route==='file')return route('home');return sourceBack()};
function focusTimeline(animate){const track=$('#photo-stream');if(!track)return;const cards=[...track.children],card=cards[state.memoryIndex];if(card){track.scrollTo({left:card.offsetLeft-track.offsetLeft-track.clientWidth/2+card.clientWidth/2,behavior:animate?'smooth':'instant'});cards.forEach((c,i)=>c.classList.toggle('active',i===state.memoryIndex))}$('#timeline-story')?.replaceChildren();if($('#timeline-story'))$('#timeline-story').innerHTML=finalMemoryText(memories[state.memoryIndex]);document.querySelectorAll('.timeline-years button').forEach((x,i)=>x.classList.toggle('active',i===state.memoryIndex))}
function openAi(context){state.aiContext=context||state.route;state.aiOrigin=state.route;route('ai')}
function askAi(value){const text=String(value||'').trim();if(!text)return;state.aiMessages.push({from:'me',text});let response='我听到了。你愿意从那一刻最先浮现在脑海里的画面说起吗？';if(/照片|相册|合影/.test(text))response='看着那张照片，你先注意到的是谁、什么物件，还是当时的场景？';else if(/工作|业务|订单|工厂/.test(text))response='你记得那件事最初是怎么开始的吗？';else if(/还没|想好|换个/.test(text))response='可以先停一停。你想到一个地方、一件旧物或一个人，再告诉我就好。';state.aiMessages.push({from:'ai',text:response});localStorage.setItem('memo-prototype-ai-chat-v1',JSON.stringify(state.aiMessages.slice(-30)));rerenderPreserve()}
function startListening(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return toast('这台浏览器暂不支持语音转文字，可用“录一段故事”保存原声');recognizer?.abort();recognizer=new R();recognizer.lang='zh-CN';recognizer.interimResults=false;recognizer.onresult=e=>askAi(e.results[0][0].transcript);recognizer.onerror=()=>toast('语音识别未完成，请再试一次');recognizer.start();toast('小忆在听，请说话')}
function readFullPage(){if(state.readIndex>=0){speechSynthesis.cancel();state.readIndex=-1;return rerenderPreserve()}const b=books.find(x=>x.id===state.bookId),p=editedPage(b,state.fullPageIndex);const sentences=String(p.text||'').split(/(?<=[。！？\n])/).filter(x=>x.trim());let i=0;function next(){if(i>=sentences.length){state.readIndex=-1;return rerenderPreserve()}state.readIndex=i;document.querySelectorAll('.reader-segment').forEach((x,j)=>x.classList.toggle('reading',j===i));const u=new SpeechSynthesisUtterance(sentences[i]);u.lang='zh-CN';u.rate=.82;u.onend=()=>{i++;next()};u.onerror=()=>{state.readIndex=-1;rerenderPreserve()};readingUtterance=u;speechSynthesis.speak(u)}speechSynthesis.cancel();next();rerenderPreserve()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-final]');if(!el)return;if(e.target.closest('[data-dual]'))return;e.preventDefault();e.stopImmediatePropagation();const a=el.dataset.final,id=el.dataset.id;switch(a){
case 'upload-sheet':state.uploadSheet=true;return render();
case 'close-upload':if(e.target.closest('.upload-sheet')&&!el.matches('[data-final="close-upload"]'))return;state.uploadSheet=false;return render();
case 'upload-camera':case 'upload-album':state.uploadSheet=false;route('photo');setTimeout(()=>{const input=$('#photo-file');if(!input)return;if(a==='upload-camera')input.setAttribute('capture','environment');else input.removeAttribute('capture');input.click()},40);return;
case 'upload-wechat':state.uploadSheet=false;return route('chat');
case 'upload-file':state.uploadSheet=false;return route('file');
case 'upload-photo':state.uploadSheet=false;return route('photo');
case 'agent-demo-record':return route('agent-demo-record');
case 'guide-next':state.guideIndex=(state.guideIndex+1)%GUIDES.length;state.guideChanges++;return rerenderPreserve();
case 'guide-record':return GUIDES[state.guideIndex].id==='expo'?route('agent-demo-record'):openRecord(null,GUIDES[state.guideIndex].q);
case 'all-guides':return route('guides');
case 'select-guide':state.guideIndex=Math.max(0,GUIDES.findIndex(g=>g.id===id));return route('home');
case 'focus-memory':state.memoryIndex=Number(id);state.timelinePaused=true;return focusTimeline(true);
case 'timeline-play':{const m=memories[state.memoryIndex],r=state.added.find(x=>x.title.includes(m.title));if(r)return playAudio(r.id);speakText(m.story);return toast('正在朗读示例文字；自己录入的原声可在经历列表回听')}
case 'timeline-text':return $('#timeline-story')?.scrollIntoView({behavior:'smooth'});
case 'open-book':state.pageIndex=1;return render();
case 'spread-prev':state.pageIndex=Math.max(0,state.pageIndex-2);$('#spread-shell')?.classList.add('turn-prev');return setTimeout(render,500);
case 'spread-next':{const b=books.find(x=>x.id===state.bookId);state.pageIndex=Math.min(b.pages.length-1,state.pageIndex+2);$('#spread-shell')?.classList.add('turn-next');return setTimeout(render,500)}
case 'page-full':state.fullPageIndex=Number(id);state.readIndex=-1;state.inlineEditing=false;return route('fullpage');
case 'edit-page':state.inlineEditing=true;return rerenderPreserve();
case 'save-page-edit':{const el2=document.getElementById('fullpaper-edit');const text=(el2?.innerText||'').trim();if(!text)return toast('这一页还没有文字');pageEdits[`${state.bookId}-${state.fullPageIndex}`]=text;localStorage.setItem('memo-prototype-page-edits-v1',JSON.stringify(pageEdits));state.inlineEditing=false;toast('本页已保存');return rerenderPreserve();}
case 'cancel-page-edit':state.inlineEditing=false;return rerenderPreserve();
case 'read-page':return readFullPage();
case 'page-question':state.pageAiQuestion=id;return rerenderPreserve();
case 'page-question-speak':{const b=books.find(x=>x.id===state.bookId),p=editedPage(b,state.fullPageIndex),qs=pageQuestions(p);return speakText(qs[state.pageAiQuestion]||qs.detail)}
case 'page-record':{const b=books.find(x=>x.id===state.bookId),p=editedPage(b,state.fullPageIndex),qs=pageQuestions(p);return openRecord(null,qs[state.pageAiQuestion]||qs.detail)}
case 'order-open':state.orderBook=id||state.bookId;return route('order');
case 'order-format':state.finalFormat=id;return rerenderPreserve();
case 'qty-minus':state.orderQty=Math.max(1,Number(state.orderQty)-1);return rerenderPreserve();
case 'qty-plus':state.orderQty=Math.min(99,Number(state.orderQty)+1);return rerenderPreserve();
case 'save-final-order':{const b=books.find(x=>x.id===state.orderBook),f=formats.find(x=>x[0]===state.finalFormat);state.orderDraft={title:b.title,format:f[1],qty:`${state.orderQty} 份`,total:f[2]*state.orderQty};return route('order-done')}
case 'ai-open':return openAi(el.dataset.context);
case 'ai-speak':return speakText(aiQuestion());
case 'ai-example':return askAi(id);
case 'ai-listen':return startListening();
case 'ai-record':return openRecord(null,aiQuestion());
case 'record-question-speak':return speakText(state.recordTitle||'今天你最想先讲哪件事？');
case 'demo-question-speak':return speakText('看着这张合影，你记得那天是怎么开始的吗？');
case 'agent-why':state.agentWhy=!state.agentWhy;return rerenderPreserve();
case 'demo-start':state.demoRecording=true;state.demoSeconds=0;clearInterval(state.demoTimer);state.demoTimer=setInterval(()=>{state.demoSeconds++;const x=$('.agent-record .record-time');if(x)x.textContent=formatSecs(state.demoSeconds);window.updateLiveTranscript?.(state.demoSeconds)},1000);return rerenderPreserve();
case 'demo-finish':clearInterval(state.demoTimer);state.demoRecording=false;state.demoSeconds=Math.max(state.demoSeconds,252);state.agentRaw=false;state.agentConfirmed=false;state.agentSupplement='';return route('agent-review');
case 'real-record':clearInterval(state.demoTimer);state.demoRecording=false;return openRecord(null,'看着这张合影，你记得那天是怎么开始的吗？');
case 'draft-clean':state.agentRaw=false;return rerenderPreserve();
case 'draft-raw':state.agentRaw=true;return rerenderPreserve();
case 'draft-read':return speakText(AGENT_CLEAN);
case 'agent-confirm':state.agentConfirmed=true;return rerenderPreserve();
case 'followup-select':state.agentQuestion=id;return rerenderPreserve();
case 'agent-save':state.agentSaved=true;localStorage.setItem('memo-prototype-agent-demo-v1',JSON.stringify({saved:true,supplement:state.agentSupplement}));return route('agent-done');
case 'agent-rest':return route('home');
case 'agent-more':return route('guides');
case 'my-follow':return route('follow');
case 'friend-open':state.followFriend=id;return route('friend');
case 'news-open':state.followNews=id;return route('news');
case 'friend-share-book':{const b=books.find(x=>x.id===id);if(!b)return;state.friendMessages.push({to:state.followFriend,text:`《${b.title}》 · 陈建华的回忆册。想先让你看看这一页。`});localStorage.setItem('memo-prototype-friend-chat-v1',JSON.stringify(state.friendMessages));toast('分享预览已放进本地对话');return rerenderPreserve()}
case 'community-read':{const n=COMMUNITY.find(x=>x.id===id);if(n)speakText(n.text);return}
case 'community-share':{const n=COMMUNITY.find(x=>x.id===id);if(!n)return;if(navigator.share)navigator.share({title:n.title,text:`${n.text} — ${n.name}《${n.title}》`}).catch(()=>{});else copyText(`${n.text} — ${n.name}《${n.title}》`);return}
case 'file-delete':{state.addedFiles=state.addedFiles.filter(x=>x.id!==id);localStorage.setItem('memo-prototype-files-v1',JSON.stringify(state.addedFiles));deleteEvidenceFile(id);const idx=GUIDES.findIndex(g=>g.id===`file-guide-${id}`);if(idx>=0)GUIDES.splice(idx,1);state.guideIndex=0;return rerenderPreserve()}
}});
document.addEventListener('submit',e=>{if(e.target.id==='ai-text-form'){e.preventDefault();askAi(new FormData(e.target).get('message'))}if(e.target.id==='final-edit-form'){e.preventDefault();const text=String(new FormData(e.target).get('text')||'').trim();if(!text)return;pageEdits[`${state.bookId}-${state.fullPageIndex}`]=text;localStorage.setItem('memo-prototype-page-edits-v1',JSON.stringify(pageEdits));state.inlineEditing=false;toast('本页已保存');rerenderPreserve()}if(e.target.id==='page-ai-form'){e.preventDefault();const reply=String(new FormData(e.target).get('reply')||'').trim();if(!reply)return;const key=`${state.bookId}-${state.fullPageIndex}`;state.pageNotes[key]=reply;localStorage.setItem('memo-prototype-page-notes-v1',JSON.stringify(state.pageNotes));state.pageAiReply=reply;toast('已经记在这页的边注');rerenderPreserve()}},true);
document.addEventListener('change',e=>{if(e.target.id==='order-qty'){state.orderQty=Math.max(1,Math.min(99,Number(e.target.value)||1));rerenderPreserve()}},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='final-file-form')return;e.preventDefault();const form=e.target,file=form.querySelector('input[type="file"]')?.files?.[0],data=new FormData(form),title=String(data.get('title')||'').trim(),note=String(data.get('note')||'').trim();if(!file||!title)return;const id=`evidence-${Date.now()}`;if(!await putEvidenceFile(id,file))return toast('文件未能保存，请换一个浏览器重试');state.addedFiles.unshift({id,name:file.name,title,note});localStorage.setItem('memo-prototype-files-v1',JSON.stringify(state.addedFiles));toast('文件已保存，小忆会把它作为话题线索');rerenderPreserve()},true);
document.addEventListener('submit',e=>{if(e.target.id!=='friend-text-form')return;e.preventDefault();const text=String(new FormData(e.target).get('text')||'').trim();if(!text)return;state.friendMessages.push({to:state.followFriend,text});localStorage.setItem('memo-prototype-friend-chat-v1',JSON.stringify(state.friendMessages));rerenderPreserve()},true);
document.addEventListener('submit',e=>{if(e.target.id!=='agent-supplement-form')return;e.preventDefault();state.agentSupplement=String(new FormData(e.target).get('supplement')||'').trim();rerenderPreserve();toast(state.agentSupplement?'补充已记在边注':'今天可以先不补充')},true);
document.addEventListener('mouseenter',e=>{if(e.target.closest?.('#photo-stream'))state.timelinePaused=true},true);
document.addEventListener('mouseleave',e=>{if(e.target.closest?.('#photo-stream')&&!e.target.closest?.('.timeline-photo'))state.timelinePaused=false},true);
function communityBook(n){return `<div class="community-book-preview cb-${n.id}"><div class="cb-cover"><img src="${asset(n.image)}" alt=""><span><small>口述回忆册</small><strong>${esc(n.title)}</strong><em>${esc(n.name)} · 口述</em></span></div><div class="cb-page"><small>节选 · 第 1 页</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><b>01</b></div></div>`;}
communityPage=function(){return `<section class="screen community-final"><div class="topline"><span class="eyebrow">故事广场</span><button class="tiny-action" data-final="ai-open" data-context="community">小忆 ›</button></div><h1 class="subheading">听听他们的故事</h1>${assistantMini('community','听到一段熟悉的经历，也可以告诉我。')}<div class="section-head"><h2>专业访谈与写作</h2><span class="live-indicator">● 直播中</span></div><div class="pro-strip">${PROS.map(p=>`<button class="pro-card" data-extra="pro" data-id="${p.id}"><img class="pro-face" src="${asset(p.avatar)}" alt="${esc(p.name)}头像">${p.live?'<i class="live-pill">直播中</i>':''}<strong>${esc(p.name)}</strong><small>${esc(p.title)}</small><span>★ ${p.rating}</span></button>`).join('')}</div><div class="pro-note">访谈师与写作者可协助把确认过的内容做成专业版本。</div><div class="section-head"><h2>故事动态</h2></div>${COMMUNITY.map(n=>`<article class="moment-card"><div class="moment-person"><img src="${asset(n.avatar)}" alt="${esc(n.name)}头像"><span><strong>${esc(n.name)}</strong><small>${n.city} · ${n.tag}</small></span></div><p class="moment-copy">${esc(n.text)}</p><button class="moment-photos" data-extra="community" data-id="${n.id}"><img class="big" src="${asset(n.photos[0])}" alt="${esc(n.title)}"><img src="${asset(n.photos[1])}" alt=""><img src="${asset(n.photos[2])}" alt=""></button>${communityBook(n)}<div class="moment-actions"><button data-final="community-read" data-id="${n.id}">▶ 朗读</button><button data-final="community-share" data-id="${n.id}">分享</button><button data-extra="community" data-id="${n.id}">打开 ›</button></div></article>`).join('')}</section>`};
communityDetail=function(){const n=COMMUNITY.find(x=>x.id===state.selectedCommunity);if(!n)return communityPage();return `<section class="screen subscreen community-detail-final">${headerBack('广场')}<div class="moment-person"><img src="${asset(n.avatar)}" alt="${esc(n.name)}头像"><span><strong>${esc(n.name)}</strong><small>${n.age} 岁 · ${n.city}</small></span></div><h1 class="subheading">${esc(n.title)}</h1><p class="story-text">${esc(n.text)}</p><div class="detail-photo-grid">${n.photos.map(x=>`<img src="${asset(x)}" alt="${esc(n.title)}相关照片">`).join('')}</div><div class="section-head"><h2>这本回忆册</h2></div>${communityBook(n)}<div class="moment-actions"><button data-final="community-read" data-id="${n.id}">▶ 朗读故事</button><button data-final="community-share" data-id="${n.id}">分享</button></div><div class="section-head"><h2>听友评论</h2></div><div class="cm-list">${(n.comments||[]).map(c=>`<div class="cm-row"><strong>${esc(c[0])}</strong><p>${esc(c[1])}</p></div>`).join('')||'<p class="subtext">还没有评论。</p>'}</div></section>`};
proDetail=function(){const p=PROS.find(x=>x.id===state.selectedPro);if(!p)return communityPage();return `<section class="screen subscreen pro-final">${headerBack('专业服务')}<div class="pro-hero"><img src="${asset(p.avatar)}" alt="${esc(p.name)}头像"><div><h1>${esc(p.name)}</h1><p>${esc(p.title)} · ★ ${p.rating}</p>${p.live?'<i class="live-pill">直播中</i>':''}</div></div><div class="pro-workflow soft-card"><strong>合作方式</strong><p>先听你的原声与已确认的经历，再参考你授权的照片和家人线索安排访谈。写成专业版本后，由你逐段核对。</p></div><div class="section-head"><h2>选择服务</h2></div>${p.services.map((s,i)=>`<button class="option-row ${state.selectedService===i?'selected':''}" data-extra="service" data-id="${i}"><span><strong>${esc(s[0])}</strong><small>结合录音、照片与经过本人确认的事件</small></span><b>${esc(s[1])}</b></button>`).join('')}<button class="primary green full" data-extra="booking-pro" style="margin-top:14px">预览咨询方案</button></section>`};
